def transform(grid):
    out = [row[:] for row in grid]
    R, C = len(grid), len(grid[0])
    seen = set()
    for r in range(R):
        for c in range(C):
            color = grid[r][c]
            if color == 6 or (r, c) in seen:
                continue
            cells, stack = [], [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < R and 0 <= xx < C and grid[yy][xx] == color and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            y0, y1 = min(y for y,x in cells), max(y for y,x in cells)
            x0, x1 = min(x for y,x in cells), max(x for y,x in cells)
            if y1-y0 >= 2 and x1-x0 >= 2 and all(grid[y0][x] == color and grid[y1][x] == color for x in range(x0,x1+1)) and all(grid[y][x0] == color and grid[y][x1] == color for y in range(y0,y1+1)):
                fill = 7 if ((y1-y0-1)*(x1-x0-1)) % 2 else 2
                for y in range(y0+1,y1):
                    for x in range(x0+1,x1): out[y][x] = fill
    return out
